import assert from 'node:assert/strict'
import {test,after} from 'node:test'
import {mkdtemp,rm,readFile} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import {DatabaseSync} from 'node:sqlite'
import {createApplication} from '../server/http.mjs'
import {Repository} from '../server/repository.mjs'
import {today} from '../.server/domain/constants.js'
const operationDate=today()
const dir=await mkdtemp(join(tmpdir(),'sica-server-')),password='Sica-Only-Test-2026',origin='http://sica.test'
const app=await createApplication({filename:join(dir,'sica.sqlite'),adminPassword:password,origins:[origin]})
await new Promise(resolve=>app.server.listen(0,'127.0.0.1',resolve))
const base=`http://127.0.0.1:${app.server.address().port}/api/`
after(async()=>{await new Promise(resolve=>app.server.close(resolve));await app.repository.close();await rm(dir,{recursive:true,force:true})})
async function request(path,{auth,input,requestOrigin=origin,csrf=true}={}){const response=await fetch(base+path,{method:input===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-SICA-Client':'web',Origin:requestOrigin,...(auth?{Cookie:auth.cookie,...(csrf?{'X-SICA-CSRF':auth.csrf}:{})}:{})},body:input===undefined?undefined:JSON.stringify(input)});const json=await response.json();return {status:response.status,json,cookie:response.headers.get('set-cookie')}}
async function login(username='admin',pass=password){const result=await request('login',{input:{username,password:pass,remember:false}});assert.equal(result.status,200);return {cookie:result.cookie.split(';')[0],csrf:result.json.csrf,snapshot:result.json}}
const admin=await login()
const command=(auth,command,revision=app.repository.read().revision,requestId=crypto.randomUUID())=>request('commands',{auth,input:{revision,requestId,command}})
test('anonymous access, cross-origin posts and missing CSRF are denied',async()=>{assert.equal((await request('state')).status,401);assert.equal((await request('login',{input:{username:'admin',password},requestOrigin:'https://untrusted.test'})).status,403);assert.equal((await request('commands',{auth:admin,csrf:false,input:{revision:0,requestId:crypto.randomUUID(),command:{type:'demo.load'}}})).status,403);assert.equal((await request('login',{input:{username:'admin',password:'incorrect'}})).status,401)})
test('server snapshots omit password hashes and salts, while session cookie is HttpOnly and Strict',async()=>{const result=await request('state',{auth:admin});assert.equal(result.status,200);assert.ok(result.json.state.masters.users.every(u=>!u.passwordHash&&!u.salt&&!u.passwordIterations));const raw=await request('login',{input:{username:'admin',password}});assert.match(raw.cookie,/HttpOnly/);assert.match(raw.cookie,/SameSite=Strict/);assert.doesNotMatch(raw.cookie,/Max-Age/)})
test('commands commit atomically, replay once, and reject stale revisions or altered replay payloads',async()=>{const revision=app.repository.read().revision,id=crypto.randomUUID(),input={type:'demo.load'};const first=await command(admin,input,revision,id);assert.equal(first.status,200);const replay=await command(admin,input,revision,id);assert.equal(replay.status,200);assert.equal(replay.json.duplicate,true);assert.equal(replay.json.revision,revision+1);assert.equal((await command(admin,{type:'master.save',key:'banks',item:{id:'extra-bank',name:'Banco extra'}},revision)).status,409);assert.equal((await command(admin,{type:'cheque.delete',id:'inventado'},revision,id)).status,409);const state=app.repository.read().state;assert.equal(state.products.length,4);assert.equal(state.audit.length,0);assert.equal(app.repository.publicState(admin.snapshot.session).state.audit.length,1)})
test('permissions are derived from server user, not submitted role or an invented path',async()=>{const user={id:'warehouse',name:'Depósito de prueba',username:'deposito',role:'Depósito',active:true,permissions:''};assert.equal((await command(admin,{type:'users.save',item:user,password:'Warehouse-Test-2026'})).status,200);const warehouse=await login('deposito','Warehouse-Test-2026');assert.equal((await command(warehouse,{type:'stock.adjust',productId:'inventado',depositId:'principal',quantity:1,reason:'No autorizado',date:operationDate,role:'Administrador General',path:'/productos/articulos'})).status,403);assert.equal((await command(warehouse,{type:'master.save',key:'users',item:{id:'malicious',name:'Admin',username:'malicious',role:'Administrador General',active:true}})).status,400);const snapshot=await request('state',{auth:warehouse});assert.equal(snapshot.json.state.entries.length,0);assert.equal(snapshot.json.state.audit.length,0);assert.equal(snapshot.json.state.treasuryMoves.length,0)})
test('failed stock operation leaves revision, audit and quantities unchanged',async()=>{const {state,revision}=app.repository.read(),product=state.products.find(p=>p.sku==='REM-M-NEG'),before=app.repository.publicState(admin.snapshot.session).state.audit.length;const result=await command(admin,{type:'stock.adjust',productId:product.id,depositId:'principal',quantity:-1000,reason:'Prueba de rollback',date:operationDate});assert.equal(result.status,400);assert.equal(app.repository.read().revision,revision);assert.deepEqual(app.repository.read().state.stockMoves,state.stockMoves);assert.equal(app.repository.publicState(admin.snapshot.session).state.audit.length,before)})
test('concurrent requests from the same revision cannot overwrite each other',async()=>{const revision=app.repository.read().revision;const results=await Promise.all([command(admin,{type:'master.save',key:'banks',item:{id:'bank-a',name:'Banco A'}},revision),command(admin,{type:'master.save',key:'banks',item:{id:'bank-b',name:'Banco B'}},revision)]);assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);assert.equal(app.repository.read().state.masters.banks.filter(b=>['bank-a','bank-b'].includes(b.id)).length,1)})
test('deactivation revokes an existing session immediately and the last administrator cannot be removed',async()=>{const warehouse=await login('deposito','Warehouse-Test-2026');assert.equal((await command(admin,{type:'users.save',item:{id:'warehouse',name:'Depósito de prueba',username:'deposito',role:'Depósito',active:false,permissions:''}})).status,200);assert.equal((await request('state',{auth:warehouse})).status,401);const result=await command(admin,{type:'users.save',item:{id:'admin',name:'Administrador',username:'admin',role:'Administrador General',active:false,permissions:''}});assert.equal(result.status,400);assert.ok(app.repository.read().state.masters.users.find(u=>u.id==='admin').active)})
test('restore preserves server credentials, records recovery, and requires administrator',async()=>{const backup=await request('backup',{auth:admin});assert.equal(backup.status,200);const previousName=backup.json.settings.name,state=backup.json;state.settings.name='Empresa restaurada de prueba';state.masters.users=[{id:'foreign',name:'Administrador importado',username:'foreign',active:true,role:'Administrador General',permissions:''}];const result=await request('restore',{auth:admin,input:{revision:app.repository.read().revision,requestId:crypto.randomUUID(),command:{state}}});assert.equal(result.status,200);assert.equal(app.repository.read().state.settings.name,'Empresa restaurada de prueba');assert.ok(app.repository.read().state.masters.users.find(u=>u.id==='admin'));assert.equal(app.repository.db.prepare('SELECT COUNT(*) AS n FROM recovery').get().n,1);const recovery=await request('recovery',{auth:admin});assert.equal(recovery.status,200);assert.equal(recovery.json.length,1);const previous=await request('recovery/'+recovery.json[0].id,{auth:admin});assert.equal(previous.json.settings.name,previousName);await login()})
test('SQLite backup is readable and server state persists across a second repository connection',async()=>{const filename=await app.repository.backupFile(join(dir,'backups'));const bytes=await readFile(filename);assert.equal(bytes.subarray(0,16).toString(),'SQLite format 3\u0000');const connection=new DatabaseSync(filename);assert.ok(connection.prepare('SELECT revision FROM companies WHERE id=?').get('sica').revision>0);connection.close();const reopened=await Repository.open({filename:join(dir,'sica.sqlite')});assert.equal(reopened.read().state.settings.name,'Empresa restaurada de prueba');reopened.verifyAudit();await reopened.close()})
test('tenant namespaces do not share sessions or operational state',async()=>{const other=await Repository.open({filename:join(dir,'sica.sqlite'),companyId:'other',adminPassword:'Other-Tenant-Test-2026'});const token=admin.cookie.split('=')[1];assert.throws(()=>other.auth(token),/sesión/);assert.equal(other.read().state.products.length,0);await other.close()})
test('customized note-only profile receives no commercial or financial collections',async()=>{const item={id:'notes-only',name:'Notas de prueba',username:'notas',role:'Personalizado',permissions:'/herramientas/notas',active:true,passwordHash:'injected',salt:'injected'};assert.equal((await command(admin,{type:'users.save',item,password:'Notes-Only-Test-2026'})).status,200);const user=await login('notas','Notes-Only-Test-2026'),result=await request('state',{auth:user});for(const key of ['documents','parties','products','entries','treasuryMoves','stockMoves','cheques','audit'])assert.equal(result.json.state[key].length,0,key);for(const key of ['treasury','banks','taxRules','production','priceLists'])assert.equal(result.json.state.masters[key].length,0,key);assert.equal((await request('backup',{auth:user})).status,403);assert.equal((await request('recovery',{auth:user})).status,403);assert.equal((await request('restore',{auth:user,input:{revision:app.repository.read().revision,requestId:crypto.randomUUID(),command:{state:app.repository.read().state}}})).status,403);assert.notEqual(app.repository.read().state.masters.users.find(u=>u.id==='notes-only').passwordHash,'injected')})
test('master commands discard undeclared fields and reject missing required references',async()=>{const result=await command(admin,{type:'master.save',key:'banks',item:{id:'bank-clean',name:'Banco limpio',passwordHash:'injected',role:'Administrador General',active:true}});assert.equal(result.status,200);const bank=app.repository.read().state.masters.banks.find(b=>b.id==='bank-clean');assert.equal(bank.passwordHash,undefined);assert.equal(bank.role,undefined);const revision=app.repository.read().revision;assert.equal((await command(admin,{type:'master.save',key:'deposits',item:{id:'deposit-bad',name:'Sin sucursal'}})).status,400);assert.equal(app.repository.read().revision,revision)})
test('a user deactivated while password verification runs cannot establish a new session',async()=>{const item={id:'warehouse',name:'Depósito de prueba',username:'deposito',role:'Depósito',active:true,permissions:''};assert.equal((await command(admin,{type:'users.save',item})).status,200);const pending=app.repository.login('deposito','Warehouse-Test-2026',false,'login-race-test');assert.equal((await command(admin,{type:'users.save',item:{...item,active:false}})).status,200);await assert.rejects(pending,/válida/)})
test('tampered audit backup and missing audit key are rejected before operation',async()=>{const filename=await app.repository.backupFile(join(dir,'integrity'));const connection=new DatabaseSync(filename);connection.prepare('UPDATE audit SET record=? WHERE id=(SELECT MIN(id) FROM audit)').run(JSON.stringify({action:'modificada'}));connection.close();await assert.rejects(Repository.open({filename}),/cadena de auditoría/);await rm(filename+'.audit-key');await assert.rejects(Repository.open({filename}),/Falta la clave/)})
test('sale-only users can read required combos and invalid compositions cannot be saved by API',async()=>{const combo={id:'combo-server',name:'Combo servidor',components:'REM-M-NEG:2, PANT-42-AZ:1',price:50000};assert.equal((await command(admin,{type:'master.save',key:'combos',item:combo})).status,200);const revision=app.repository.read().revision;assert.equal((await command(admin,{type:'master.save',key:'combos',item:{...combo,components:'UNKNOWN:1'}})).status,400);assert.equal(app.repository.read().revision,revision);assert.equal((await command(admin,{type:'users.save',item:{id:'sales-combo',name:'Ventas con combos',username:'ventascombo',role:'Personalizado',active:true,permissions:'/clientes/ventas'},password:'Sales-Combo-Test-2026'})).status,200);const sales=await login('ventascombo','Sales-Combo-Test-2026'),snapshot=await request('state',{auth:sales});assert.equal(snapshot.json.state.masters.combos[0].id,combo.id);assert.equal((await command(sales,{type:'master.save',key:'combos',item:{...combo,price:1}})).status,403);const notes=await login('notas','Notes-Only-Test-2026');assert.equal((await request('state',{auth:notes})).json.state.masters.combos.length,0)})
test('fiscal endpoints enforce session and CSRF and cannot authorize without server credentials',async()=>{assert.equal((await request('fiscal/status')).status,401);const status=await request('fiscal/status',{auth:admin});assert.deepEqual(status.json,{environment:'homologacion',configured:false,productionEnabled:false});assert.equal((await request('fiscal/operate',{auth:admin,csrf:false,input:{documentId:'inventado',revision:app.repository.read().revision,action:'autorizar'}})).status,403);const state=app.repository.read().state,party=state.parties.find(p=>p.side==='cliente'),product=state.products.find(p=>p.sku==='REM-M-NEG'),input={kind:'factura',side:'cliente',letter:'A',date:operationDate,due:operationDate,branchId:'central',partyId:party.id,lines:[{productId:product.id,description:product.name,quantity:1,unit:'Unidad',price:10000,tax:'21',discount:0}],payments:[],allocations:[],perceptions:0,sourceId:'',observations:'Prueba fiscal sin conexión',responsible:'Fake actor',costCenter:'',depositId:'principal',official:false,valued:true,seller:'',priceList:'general'};assert.equal((await command(admin,{type:'document.create',document:input})).status,200);const document=app.repository.read().state.documents.at(-1),revision=app.repository.read().revision;assert.equal((await request('fiscal/preview',{auth:admin,input:{documentId:document.id,options:{}}})).status,400);assert.equal((await request('fiscal/operate',{auth:admin,input:{documentId:document.id,revision,options:{},action:'autorizar'}})).status,503);assert.equal(app.repository.read().revision,revision);assert.equal(app.repository.db.prepare('SELECT COUNT(*) AS n FROM fiscal_jobs').get().n,0);const notes=await login('notas','Notes-Only-Test-2026');assert.equal((await request('fiscal/preview',{auth:notes,input:{documentId:document.id}})).status,403)})
test('stock transfer is atomic, idempotent, session-attributed and available to a transfer-only profile',async()=>{
 assert.equal((await command(admin,{type:'master.save',key:'deposits',item:{id:'transfer-target',name:'Destino de prueba',branchId:'central'}})).status,200)
 assert.equal((await command(admin,{type:'users.save',item:{id:'transfer-only',name:'Operador de traslados',username:'traslados',role:'Personalizado',permissions:'/stock/traslados',active:true},password:'Transfer-Only-Test-2026'})).status,200)
 const operator=await login('traslados','Transfer-Only-Test-2026'),snapshot=await request('state',{auth:operator})
 assert.ok(snapshot.json.state.products.length);assert.ok(snapshot.json.state.stockMoves.length);assert.ok(snapshot.json.state.masters.deposits.length);assert.equal(snapshot.json.state.documents.length,0);assert.equal(snapshot.json.state.entries.length,0)
 const product=snapshot.json.state.products.find(p=>p.sku==='REM-M-NEG'),input={type:'stock.transfer',transfer:{date:operationDate,fromId:'principal',toId:'transfer-target',reason:'Traslado HTTP',lines:[{productId:product.id,quantity:3}],responsible:'Actor inventado'}}
 const revision=app.repository.read().revision,id=crypto.randomUUID(),result=await command(operator,input,revision,id)
 assert.equal(result.status,200);assert.equal(result.json.state.stockTransfers.at(-1).responsible,'Operador de traslados');assert.equal((await command(operator,input,revision,id)).json.duplicate,true)
 const after=app.repository.read();assert.equal(after.revision,revision+1);assert.equal(after.state.stockMoves.filter(m=>m.transferId===after.state.stockTransfers.at(-1).id).length,2)
 assert.equal((await command(operator,{...input,transfer:{...input.transfer,lines:[{productId:product.id,quantity:1000}]}})).status,400);assert.equal(app.repository.read().revision,after.revision);assert.deepEqual(app.repository.read().state.stockMoves,after.state.stockMoves)
 assert.equal((await command(operator,{type:'stock.adjust',productId:product.id,depositId:'principal',quantity:1,reason:'Sin permiso',date:operationDate})).status,403)
 const notes=await login('notas','Notes-Only-Test-2026');assert.equal((await request('state',{auth:notes})).json.state.stockTransfers.length,0);assert.equal((await command(notes,input)).status,403)
})
let productionOperator
test('production HTTP workflow freezes requirements, enforces sequence and records the authenticated operator',async()=>{
 assert.equal((await command(admin,{type:'users.save',item:{id:'production-http',name:'Operador de fabricación',username:'fabricacion',role:'Personalizado',permissions:'/produccion',active:true},password:'Production-Only-Test-2026'})).status,200)
 productionOperator=await login('fabricacion','Production-Only-Test-2026')
 const state=app.repository.read().state,raw=state.products.find(p=>p.sku==='REM-M-NEG'),output=state.products.find(p=>p.sku==='PANT-42-AZ')
 for(const [key,item] of [['workCenters',{id:'factory-http',name:'Taller HTTP',branchId:'central',hours:4,capacity:1,workDays:'1,2,3,4,5,6,7'}],['routes',{id:'route-http',name:'Ruta HTTP',steps:'Corte → Control',workCenterId:'factory-http',hours:1}],['production',{id:'order-http',name:'Lote HTTP',branchId:'central',productId:output.id,quantity:1,start:operationDate,end:state.settings.exerciseEnd,workCenterId:'factory-http',routeId:'route-http',status:'Planificada'}],['materials',{id:'material-http',name:'Tela HTTP',orderId:'order-http',productId:raw.id,quantity:1,unit:raw.unit,depositId:'principal'}]])assert.equal((await command(productionOperator,{type:'master.save',key,item})).status,200)
 const revision=app.repository.read().revision,id=crypto.randomUUID(),prepare={type:'production.prepare',orderId:'order-http'}
 assert.equal((await command(productionOperator,prepare,revision,id)).status,200);assert.equal((await command(productionOperator,prepare,revision,id)).json.duplicate,true)
 const plan=app.repository.read().state.productionPlans.find(p=>p.orderId==='order-http');assert.equal(plan.preparedBy,'Operador de fabricación')
 if(operationDate<state.settings.exerciseEnd){const revision=app.repository.read().revision,attempt=await command(admin,{type:'settings.save',settings:{...state.settings,exerciseEnd:operationDate}});assert.equal(attempt.status,400);assert.match(attempt.json.error,/producción/);assert.equal(app.repository.read().revision,revision)}
 assert.equal((await command(productionOperator,{type:'master.save',key:'materials',item:{...app.repository.read().state.masters.materials.find(m=>m.id==='material-http'),quantity:10}})).status,400)
 const before=app.repository.read(),step=(op,action)=>({type:'production.step',orderId:'order-http',operationId:op.id,action,date:operationDate,actualHours:0.5,responsible:'Inventado'})
 assert.equal((await command(productionOperator,step(plan.operations[1],'iniciar'))).status,400);assert.equal(app.repository.read().revision,before.revision)
 assert.equal((await command(productionOperator,{type:'production.finish',orderId:'order-http',depositId:'principal',date:operationDate})).status,400)
 for(const op of plan.operations){assert.equal((await command(productionOperator,step(op,'iniciar'))).status,200);assert.equal((await command(productionOperator,step(op,'completar'))).status,200)}
 assert.ok(app.repository.read().state.productionPlans.find(p=>p.id===plan.id).operations.every(o=>o.startedBy==='Operador de fabricación'&&o.finishedBy==='Operador de fabricación'))
 const finish={type:'production.finish',orderId:'order-http',depositId:'principal',date:operationDate},finished=await command(productionOperator,finish)
 assert.equal(finished.status,200);assert.equal(finished.json.state.masters.production.find(o=>o.id==='order-http').status,'Terminada');assert.equal(finished.json.state.stockMoves.filter(m=>m.documentId==='order-http').length,2);assert.equal((await command(productionOperator,finish)).status,400)
 const notes=await login('notas','Notes-Only-Test-2026');assert.equal((await request('state',{auth:notes})).json.state.productionPlans.length,0);assert.equal((await command(notes,prepare)).status,403)
})
test('concurrent production preparations cannot reserve the same remaining daily capacity',async()=>{
 const state=app.repository.read().state,raw=state.products.find(p=>p.sku==='REM-M-NEG'),output=state.products.find(p=>p.sku==='PANT-42-AZ')
 for(const [key,item] of [['workCenters',{id:'center-race',name:'Centro de una hora',branchId:'central',hours:1,capacity:1,workDays:'1,2,3,4,5,6,7'}],['routes',{id:'route-race',name:'Ruta de una hora',steps:'Operación única',workCenterId:'center-race',hours:1}]])assert.equal((await command(productionOperator,{type:'master.save',key,item})).status,200)
 for(const suffix of ['a','b'])for(const [key,item] of [['production',{id:'order-race-'+suffix,name:'Lote '+suffix,branchId:'central',productId:output.id,quantity:1,start:operationDate,end:operationDate,workCenterId:'center-race',routeId:'route-race',status:'Planificada'}],['materials',{id:'material-race-'+suffix,name:'Tela '+suffix,orderId:'order-race-'+suffix,productId:raw.id,quantity:1,unit:raw.unit,depositId:'principal'}]])assert.equal((await command(productionOperator,{type:'master.save',key,item})).status,200)
 const before=app.repository.read(),results=await Promise.all(['a','b'].map(suffix=>command(productionOperator,{type:'production.prepare',orderId:'order-race-'+suffix},before.revision)))
 assert.deepEqual(results.map(r=>r.status).sort(),[200,409]);const current=app.repository.read(),missing=['a','b'].find(suffix=>!current.state.productionPlans.some(p=>p.orderId==='order-race-'+suffix))
 assert.equal((await command(productionOperator,{type:'production.prepare',orderId:'order-race-'+missing})).status,400);assert.equal(app.repository.read().revision,current.revision);assert.deepEqual(app.repository.read().state.stockMoves,before.state.stockMoves);assert.equal(app.repository.read().state.productionPlans.filter(p=>p.workCenterId==='center-race').length,1)
})
