 const instance=await createApplication({filename:join(dir,'journal-reversal.sqlite'),adminPassword:password,origins:[origin]});await new Promise(resolve=>instance.server.listen(0,'127.0.0.1',resolve));const base=`http://127.0.0.1:${instance.server.address().port}/api/`,model=await import('../.server/domain/journal-reversals.js')
