test('multi-company HTTP scopes credentials, cookies, CSRF, permissions, replays, restores, fiscal clients and session revocation',async()=>{
 const configs=[{id:'textil',label:'Textil Tucumán',filename:join(dir,'multi-textil.sqlite'),adminPassword:'Multi-Textil-Test-2026',arcaClient:{status:()=>({configured:false,environment:'homologacion',productionEnabled:false,company:'textil'})}},{id:'servicios',label:'Servicios',filename:join(dir,'multi-servicios.sqlite'),adminPassword:'Multi-Servicios-Test-2026',arcaClient:{status:()=>({configured:false,environment:'homologacion',productionEnabled:false,company:'servicios'})}}]
 const instance=await createApplication({companies:configs,origins:[origin]});await new Promise(resolve=>instance.server.listen(0,'127.0.0.1',resolve));const base=`http://127.0.0.1:${instance.server.address().port}/api/`
 const call=async(company,path,auth,input)=>{const r=await fetch(base+(company?`company/${company}/`:'')+path,{method:input?'POST':'GET',headers:{'Content-Type':'application/json','X-SICA-Client':'web',Origin:origin,...(auth?{Cookie:auth.cookie,'X-SICA-CSRF':auth.csrf}:{})},body:input?JSON.stringify(input):undefined});return {status:r.status,json:await r.json(),cookie:r.headers.get('set-cookie')}}
 const signIn=async(company,password)=>{const r=await call(company,'login',null,{username:'admin',password,remember:true,terminalName:'Ensayo multiempresa'});assert.equal(r.status,200);return {cookie:r.cookie.split(';')[0],csrf:r.json.csrf,snapshot:r.json,fullCookie:r.cookie}}
 const invoke=(company,auth,command,revision=instance.repositories.get(company).read().revision,requestId=crypto.randomUUID())=>call(company,'commands',auth,{revision,requestId,command})
 try{
  const registry=await call(null,'companies');assert.deepEqual(registry.json,{defaultId:'textil',companies:configs.map(({id,label})=>({id,label}))});assert.equal(JSON.stringify(registry.json).includes('filename'),false);assert.equal(JSON.stringify(registry.json).includes('Password'),false)
  const a=await signIn('textil',configs[0].adminPassword),b=await signIn('servicios',configs[1].adminPassword)
  assert.equal(a.snapshot.company.id,'textil');assert.equal(b.snapshot.company.id,'servicios');assert.match(a.fullCookie,/Path=\/api;/);assert.match(b.fullCookie,/Path=\/api\/company\/servicios/);assert.notEqual(a.cookie.split('=')[0],b.cookie.split('=')[0]);assert.match(a.fullCookie,/HttpOnly; SameSite=Strict/)
  assert.equal((await call('servicios','login',null,{username:'admin',password:configs[0].adminPassword})).status,401)
  for(const [company,auth] of [['textil',b],['servicios',a]])for(const path of ['state','sessions','backup','recovery','fiscal/status'])assert.equal((await call(company,path,auth)).status,401)
  assert.equal((await call('missing','state',a)).status,404);assert.equal((await call('textil','state',{...a,cookie:`irrelevant=1; ${a.cookie}`})).status,200)
  const combined={cookie:`${a.cookie}; ${b.cookie}`,csrf:b.csrf};assert.equal((await call('servicios','state',combined)).json.company.id,'servicios');assert.equal((await call(null,'state',a)).json.company.id,'textil')
  const sameId=crypto.randomUUID(),note=company=>({type:'master.save',key:'notes',item:{id:'shared-record-id',name:`Nota de ${company}`,text:`Sólo ${company}`}})
  const saved=await Promise.all([invoke('textil',a,note('textil'),0,sameId),invoke('servicios',b,note('servicios'),0,sameId)])
  assert.deepEqual(saved.map(r=>r.status),[200,200]);assert.equal((await invoke('textil',a,note('textil'),0,sameId)).json.duplicate,true);assert.equal((await invoke('servicios',b,note('servicios'),0,sameId)).json.duplicate,true)
  assert.equal((await invoke('textil',{...a,csrf:b.csrf},note('otra'))).status,403)
  assert.equal((await call('textil','state',a)).json.state.masters.notes[0].name,'Nota de textil');assert.equal((await call('servicios','state',b)).json.state.masters.notes[0].name,'Nota de servicios')
  for(const company of ['textil','servicios']){const auth=company==='textil'?a:b;assert.equal((await call(company,'fiscal/status',auth)).json.company,company)}
  const bSession=(await call('servicios','sessions',b)).json[0];assert.equal((await invoke('textil',a,{type:'sessions.revoke',sessionId:bSession.id,reason:'Intento de otra empresa'})).status,409)
  const aState=instance.repositories.get('textil').read().state,beforeB=instance.repositories.get('servicios').read();aState.settings.name='Empresa Textil aislada';assert.equal((await call('textil','restore',a,{revision:1,requestId:crypto.randomUUID(),command:{state:aState}})).status,200);assert.deepEqual(instance.repositories.get('servicios').read(),beforeB)
  const recovery=(await call('textil','recovery',a)).json[0];assert.equal((await call('servicios',`recovery/${recovery.id}`,b)).status,404);assert.equal((await call('textil','backup',a)).json.settings.name,'Empresa Textil aislada');assert.equal((await call('servicios','backup',b)).json.masters.notes[0].name,'Nota de servicios')
  assert.equal((await invoke('textil',a,{type:'users.save',item:{id:'scoped-user',name:'Usuario de depósito',username:'scoped',role:'Depósito',active:true,permissions:''},password:'Scoped-Textil-User-2026'})).status,200)
  const readerLogin=await call('textil','login',null,{username:'scoped',password:'Scoped-Textil-User-2026'}),reader={cookie:readerLogin.cookie.split(';')[0],csrf:readerLogin.json.csrf};assert.equal(readerLogin.status,200);assert.equal((await invoke('textil',reader,{type:'settings.save',settings:instance.repositories.get('textil').read().state.settings})).status,403);assert.equal((await call('servicios','login',null,{username:'scoped',password:'Scoped-Textil-User-2026'})).status,401)
  assert.equal((await call('textil','logout',a,{})).status,200);assert.equal((await call('textil','state',a)).status,401);assert.equal((await call('servicios','state',b)).status,200)
  for(const repo of instance.repositories.values()){repo.verifyAudit();assert.equal(repo.db.prepare('PRAGMA integrity_check').get().integrity_check,'ok')}
 }finally{await new Promise(resolve=>instance.server.close(resolve));await instance.close()}
})

