test('card disputes reproduce scoped reviews, preserve receipts and tax, resolve with authenticated identity, replay safely and reject forged recovery',async()=>{
 const {cardDisputesFixture}=await import('./card-disputes-fixture.mjs'),model=await import('../.server/domain/card-disputes.js'),f=cardDisputesFixture(),filename=join(dir,'card-disputes.sqlite'),instance=await createApplication({filename,adminPassword:password,origins:[origin]})
 await new Promise(resolve=>instance.server.listen(0,'127.0.0.1',resolve));const base=`http://127.0.0.1:${instance.server.address().port}/api/`
 const call=async(path,auth,input)=>{const r=await fetch(base+path,{method:input?'POST':'GET',headers:{'Content-Type':'application/json','X-SICA-Client':'web',Origin:origin,...(auth?{Cookie:auth.cookie,'X-SICA-CSRF':auth.csrf}:{})},body:input?JSON.stringify(input):undefined});return {status:r.status,json:await r.json(),cookie:r.headers.get('set-cookie')}}
 const login=async(username='admin')=>{const r=await call('login',null,{username,password});assert.equal(r.status,200);return {cookie:r.cookie.split(';')[0],csrf:r.json.csrf}}
 const invoke=(auth,command,revision=instance.repository.read().revision,requestId=crypto.randomUUID())=>call('commands',auth,{revision,requestId,command})
 try{
  const admin=await login();assert.equal((await call('restore',admin,{revision:0,requestId:crypto.randomUUID(),command:{state:f.state}})).status,200)
  for(const [id,permissions] of [['card-operator','/finanzas/liquidaciones-tarjetas'],['card-notes','/herramientas/notas']])assert.equal((await invoke(admin,{type:'users.save',item:{id,name:id,username:id,role:'Personalizado',permissions,active:true},password})).status,200)
  const operator=await login('card-operator'),notes=await login('card-notes'),view=(await call('state',operator)).json.state,p=model.previewCardDispute(view,f.input),full=model.previewCardDispute(instance.repository.read().state,f.input)
  assert.deepEqual(p,full);assert.equal(view.entries.length,0);assert.equal(view.cardSources.length,1)
  const command={type:'cards.dispute',dispute:{...f.input,review:model.cardDisputeReview(p),responsible:'Inventado'}},before=instance.repository.read(),id=crypto.randomUUID()
  assert.equal((await invoke(notes,command)).status,403);assert.equal((await invoke(operator,{...command,dispute:{...command.dispute,review:'otro'}})).status,400);assert.equal(instance.repository.read().revision,before.revision)
  assert.equal((await invoke(operator,command,before.revision,id)).status,200);assert.equal((await invoke(operator,command,before.revision,id)).json.duplicate,true)
  let current=instance.repository.read();const claim=current.state.cardDisputes[0];assert.equal(claim.responsible,'card-operator');assert.deepEqual(current.state.documents,before.state.documents);assert.deepEqual(current.state.cardSettlements,before.state.cardSettlements)
  assert.equal((await call('state',notes)).json.state.cardDisputes.length,0);assert.equal((await call('state',notes)).json.state.cardSources.length,0)
  const resolution={disputeId:claim.id,date:f.date,reference:'REFUND-HTTP',reason:'Respuesta y acreditación parcial de procesadora.',amount:25000,outcome:'Reintegrado'},rp=model.previewCardResolution((await call('state',operator)).json.state,resolution)
  assert.deepEqual(rp,model.previewCardResolution(current.state,resolution));assert.equal((await invoke(operator,{type:'cards.resolve',resolution:{...resolution,review:model.cardDisputeReview(rp)}})).status,200)
  current=instance.repository.read();const loss={...resolution,reference:'LOSS-HTTP',amount:15000,outcome:'Pérdida'},lp=model.previewCardResolution(current.state,loss),closing={type:'cards.resolve',resolution:{...loss,review:model.cardDisputeReview(lp)}}
  const raced=await Promise.all([invoke(operator,closing,current.revision),invoke(operator,closing,current.revision)]);assert.deepEqual(raced.map(r=>r.status).sort(),[200,409])
  current=instance.repository.read();assert.equal(current.state.cardDisputes.length,3);assert.equal(current.state.cardDisputes[2].entryId,undefined);assert.equal(current.state.entries.length,before.state.entries.length+2);assert.equal(model.cardClaimRemaining(current.state,claim.id),0);assert.equal(current.state.treasuryMoves.reduce((n,m)=>n+m.amount,0),80000)
  const corrupt=structuredClone(current.state);corrupt.cardDisputes[0].preview.input.amount++
  assert.equal((await call('restore',admin,{revision:current.revision,requestId:crypto.randomUUID(),command:{state:corrupt}})).status,400);assert.equal(instance.repository.read().revision,current.revision)
  const reopened=await Repository.open({filename});try{reopened.verifyAudit();assert.deepEqual(reopened.read().state.cardDisputes,current.state.cardDisputes)}finally{await reopened.close()}
 }finally{await new Promise(resolve=>instance.server.close(resolve));await instance.close()}
})

